import{_ as l,a0 as o,w as d,s as r,ao as t,I as p,a1 as e,A as i,x as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何在 Linux 中恢復仍在活動進程中的已刪除文件 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中恢復仍在活動進程中的已刪除文件 | LCTT (201707) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中恢復仍在活動進程中的已刪除文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中恢復仍在活動進程中的已刪除文件 | LCTT (201707) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201707/20170714 HOW TO RECOVER DELETED FILES STILL RUNNING WITH ACTIVE PROCESSES ON LINUX","title":"如何在 Linux 中恢復仍在活動進程中的已刪除文件","tag":"201707","desc":""},"relativePath":"201707/20170714 HOW TO RECOVER DELETED FILES STILL RUNNING WITH ACTIVE PROCESSES ON LINUX.md","filePath":"[post].md"}'),g={name:"201707/20170714 HOW TO RECOVER DELETED FILES STILL RUNNING WITH ACTIVE PROCESSES ON LINUX.md"};function h(c,s,u,k,m,b){const n=o("Link");return d(),r("div",null,[s[14]||(s[14]=t(`<h1 id="如何在-linux-中恢復仍在活動進程中的已刪除文件" tabindex="-1">如何在 Linux 中恢復仍在活動進程中的已刪除文件 <a class="header-anchor" href="#如何在-linux-中恢復仍在活動進程中的已刪除文件" aria-label="Permalink to “如何在 Linux 中恢復仍在活動進程中的已刪除文件”">​</a></h1><blockquote><p>使用終端恢復你 Linux 系統上仍在運行進程的已刪除文件的快速指南。</p></blockquote><p>許多情況下，刪除的文件都可以恢復，比如在該文件有活動的進程在操作它，並且目前被單個或多個用户使用時。在 Linux 系統中，每個當前正在運行的進程都會獲得 ID，其被稱之為進程標識符 “PID”，並將它們存放在 <code>/proc</code> 目錄中。這正是我們恢復仍在運行的進程中（具有PID）已刪除的文件所需要的東西。這裏就是介紹我們如何做到這一點的。</p><p>假設你打開了一個壓縮文件，之後你刪除了這個文件。為了演示目的，壓縮文件稱為 “opengapps.zip”，這將是之後我們將打開和刪除的文件。</p><h3 id="計算原始文件的-md5-哈希" tabindex="-1">計算原始文件的 MD5 哈希 <a class="header-anchor" href="#計算原始文件的-md5-哈希" aria-label="Permalink to “計算原始文件的 MD5 哈希”">​</a></h3><p>刪除之前，我們將計算該文件的 MD5。這樣我們可以將原來的 MD5 哈希值與恢復文件的 MD5 哈希進行比較。這個過程將保證我們恢復的壓縮文件的完整性是一樣的，它沒有被破壞。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>md5sum opengapps.zip &gt;&gt; md5-opengapps.txt</span></span></code></pre></div><p>要顯示文本文件的內容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat md5-opengapps.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>86489b68b40d144f0e00a0ea8407f7c0  opengapps.zip</span></span></code></pre></div><p>檢查壓縮文件的 MD5 哈希值之後。我們將壓縮文件保持打開（LCTT 譯註：此處是使用 file-roller 這個圖形界面的解壓程序保持對該壓縮文件的打開，其內置在 GNOME 環境中；在桌面環境中，使用桌面工具打開一個壓縮包也能起到同樣的作用。又及，本文舉例不是很恰當，如果是刪除了某個服務進程的已經打開的配置文件，那麼這種恢復就很有意義），並將其刪除。之後，我們將從文件的恢復過程開始，步驟如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rm opengapps.zip</span></span></code></pre></div><h3 id="刪除文件的恢復過程" tabindex="-1">刪除文件的恢復過程 <a class="header-anchor" href="#刪除文件的恢復過程" aria-label="Permalink to “刪除文件的恢復過程”">​</a></h3><p>正如我們前面提到的，運行的進程在 <code>/proc</code> 目錄中。我們可以使用以下命令搜索該目錄中需要的進程：</p><p>由於我們已經知道文件名包括 .zip 擴展名，因此我們可以使用 .zip 擴展名進行搜索。它將限制輸出結果並顯示所需的進程。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ps -axu | grep .zip</span></span>
<span class="line"><span></span></span>
<span class="line"><span>m        13119  0.8  1.0 121788 30788 ?        Sl   06:17   0:00 file-roller /home/m/Downloads/Compressed/opengapps.zip</span></span>
<span class="line"><span>m        13164  0.0  0.0   5108   832 pts/20   S+   06:18   0:00 grep --color=auto .zip</span></span></code></pre></div><p>然後我們將進入到包含 PID <code>13119</code> 的目錄並打開 <code>fd</code> 子目錄。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd /proc/13119/fd</span></span></code></pre></div><p><code>fd</code> （文件描述符）目錄包含多個文件，包括我們需要恢復的文件。該文件以硬鏈接的方式鏈接到原始文件。 <code>fd</code> 目錄中的所有文件都以數字鏈接到“文件名”。因此，要確定這些文件中的哪一個鏈接到該原始文件，我們將用詳細列表選項列出 /fd 目錄。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ls -l</span></span>
<span class="line"><span></span></span>
<span class="line"><span>total 0</span></span>
<span class="line"><span>lr-x------ 1 m m 64 Jul 14 06:17 0 -&gt; /dev/null</span></span>
<span class="line"><span>lrwx------ 1 m m 64 Jul 14 06:17 1 -&gt; socket:[26161]</span></span>
<span class="line"><span>lrwx------ 1 m m 64 Jul 14 06:17 10 -&gt; anon_inode:[eventfd]</span></span>
<span class="line"><span>lr-x------ 1 m m 64 Jul 14 06:17 11 -&gt; anon_inode:inotify</span></span>
<span class="line"><span>lrwx------ 1 m m 64 Jul 14 06:17 12 -&gt; socket:[5752671]</span></span>
<span class="line"><span>lr-x------ 1 m m 64 Jul 14 06:17 13 -&gt; /home/m/Downloads/Compressed/opengapps.zip (deleted)</span></span>
<span class="line"><span>lrwx------ 1 m m 64 Jul 14 06:17 2 -&gt; socket:[26161]</span></span>
<span class="line"><span>lrwx------ 1 m m 64 Jul 14 06:17 3 -&gt; anon_inode:[eventfd]</span></span>
<span class="line"><span>lrwx------ 1 m m 64 Jul 14 06:17 4 -&gt; anon_inode:[eventfd]</span></span>
<span class="line"><span>lrwx------ 1 m m 64 Jul 14 06:17 5 -&gt; socket:[5751361]</span></span>
<span class="line"><span>lrwx------ 1 m m 64 Jul 14 06:17 6 -&gt; anon_inode:[eventfd]</span></span>
<span class="line"><span>lrwx------ 1 m m 64 Jul 14 06:17 7 -&gt; anon_inode:[eventfd]</span></span>
<span class="line"><span>lrwx------ 1 m m 64 Jul 14 06:17 8 -&gt; socket:[5751363]</span></span>
<span class="line"><span>lrwx------ 1 m m 64 Jul 14 06:17 9 -&gt; socket:[5751365]</span></span></code></pre></div><p>正如你在終端輸出中看到的，原始文件 “opengapps.zip” 已被刪除，但它仍然鏈接到一個文件名 <code>13</code>，其進程 PID <code>13119</code>。但是，我們仍然可以通過將鏈接的文件複製到安全的地方來恢復它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp 13 /home/m/Downloads/Compressed</span></span></code></pre></div><p>文件複製後。我們將返回包含恢復文件的目錄，並使用以下命令重命名它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mv 13 opengapps-recovered.zip</span></span></code></pre></div><h3 id="計算恢復文件的-md5-哈希" tabindex="-1">計算恢復文件的 MD5 哈希 <a class="header-anchor" href="#計算恢復文件的-md5-哈希" aria-label="Permalink to “計算恢復文件的 MD5 哈希”">​</a></h3><p>由於我們已經恢復了該文件。讓我們檢查該文件的完整性，這只是為了確保文件沒有損壞，並且和原來一樣。早先我們保存了原始文件的 MD5 哈希值。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>md5sum opengapps-recovered.zip &gt;&gt; md5-opengapps.txt</span></span></code></pre></div><p>該命令將檢查文件的 MD5 哈希值，並在文件中追加新恢復文件的 MD5 哈希值，以輕鬆比較兩個 MD5 哈希值。</p><p>可以顯示文本文件的內容來比較原始文件和恢復文件的 MD5 哈希值。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat md5-opengapps.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>86489b68b40d144f0e00a0ea8407f7c0  opengapps.zip</span></span>
<span class="line"><span>86489b68b40d144f0e00a0ea8407f7c0  opengapps-recovered.zip</span></span></code></pre></div><p>恢復文件的 MD5 哈希是一樣的。所以，我們成功地恢復了我們以前刪除的文件，並且恢復後文件完整性一致，並且工作正常。</p>`,30)),p("p",null,[e(n,{href:"http://www.linuxnov.com/wp-content/uploads/2017/07/Recovering-a-deleted-file-using-terminal-LinuxNov.png"},{default:i(()=>[...s[0]||(s[0]=[p("img",{src:"http://www.linuxnov.com/wp-content/uploads/2017/07/Recovering-a-deleted-file-using-terminal-LinuxNov.png",alt:""},null,-1)])]),_:1})]),s[15]||(s[15]=t('<p><strong>注意：</strong> 在某些情況下，某些文件無法通過 <code>ps -axu</code> 命令看到。 所以，嘗試檢查運行的程序，並從中恢復文件。</p><p>假設我們有一個使用 Totem 媒體播放器播放中的以 .avi 為擴展名的視頻。你需要做的就是檢查 Totem 的 PID，並按照本示例中提到的相同説明進行操作。</p><p>要查找正在運行的程序的 PID，請使用以下命令，後面跟程序的名稱。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pidof 程序名</span></span></code></pre></div><p>通過分享支持我們。</p><hr>',6)),p("p",null,[s[2]||(s[2]=a("via: ",-1)),e(n,{href:"http://www.linuxnov.com/recover-deleted-files-still-running-active-processes-linux/"},{default:i(()=>[...s[1]||(s[1]=[a("http://www.linuxnov.com/recover-deleted-files-still-running-active-processes-linux/",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=a("作者：",-1)),e(n,{href:"http://www.linuxnov.com/author/mhnassif/"},{default:i(()=>[...s[3]||(s[3]=[a("mhnassif",-1)])]),_:1}),s[7]||(s[7]=a(" 譯者：",-1)),e(n,{href:"https://github.com/geekpi"},{default:i(()=>[...s[4]||(s[4]=[a("geekpi",-1)])]),_:1}),s[8]||(s[8]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[11]||(s[11]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[9]||(s[9]=[a("LCTT",-1)])]),_:1}),s[12]||(s[12]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...s[10]||(s[10]=[a("Linux中國",-1)])]),_:1}),s[13]||(s[13]=a(" 榮譽推出",-1))])])}const T=l(g,[["render",h]]);export{C as __pageData,T as default};
